<?php require __DIR__.'/includes/functions.php';require __DIR__.'/includes/data.php';$slug=$_GET['slug']??'';$titles=['safaris'=>'Tanzania Safaris','kilimanjaro'=>'Mount Kilimanjaro','trekking'=>'Trekking in Tanzania','zanzibar'=>'Zanzibar','destinations'=>'Tanzania Destinations','day-trips'=>'Day Trips & Experiences','travel-guide'=>'Tanzania Travel Guide','about'=>'About Tanzania Wildlife Epic','contact'=>'Plan Your Trip','faq'=>'Frequently Asked Questions','migration-safaris'=>'Great Migration Safaris','luxury-safaris'=>'Luxury Tanzania Safaris','family-safaris'=>'Family Tanzania Safaris'];$title=$titles[$slug]??ucwords(str_replace('-',' ',$slug));$pageMeta=meta($title,$title.' with Tanzania Wildlife Epic.');require __DIR__.'/includes/header.php';?>
<main><section class="inner-hero"><div class="wrap"><nav class="crumb"><a href="/">Home</a> / <?=e($title)?></nav><h1><?=e($title)?></h1><p>Explore verified Tanzania travel options with a clear route structure and direct enquiry support.</p></div></section><section class="section wrap"><?php if($slug==='destinations'):?><div class="destination-grid"><?php foreach(destinations() as $d):?><article id="<?=e($d['slug'])?>"><h2><?=e($d['name'])?></h2><p><?=e($d['text'])?></p><a href="/contact">Plan a trip here →</a></article><?php endforeach;?></div><?php elseif($slug==='contact'):?><div class="contact-grid"><div><h2>Tell us what you want to do</h2><p>Send your travel dates, group size, preferred trip length and whether you want safari, trekking, Zanzibar or a combination.</p><p><strong>Phone / WhatsApp:</strong> <?=e(site_config()['site']['phone'])?><br><strong>Email:</strong> <?=e(site_config()['site']['email'])?></p></div><form class="contact-form" action="/enquiry.php" method="post"><input name="name" placeholder="Your name" required><input type="email" name="email" placeholder="Email" required><input name="phone" placeholder="Phone / WhatsApp"><input name="trip" placeholder="Trip or interest"><textarea name="message" placeholder="Dates, group size and what you would like to do" required></textarea><button class="btn gold">Send Enquiry</button></form></div><?php elseif(in_array($slug,['safaris','kilimanjaro','trekking','zanzibar','day-trips','migration-safaris','luxury-safaris','family-safaris'])):?><div class="cards"><?php $filter=array_filter(packages(),function($p)use($slug){if($slug==='safaris'||str_contains($slug,'safaris'))return $p['category']==='Safari';if($slug==='kilimanjaro')return $p['category']==='Kilimanjaro';if($slug==='trekking')return in_array($p['category'],['Kilimanjaro','Trekking']);if($slug==='zanzibar')return $p['category']==='Zanzibar';if($slug==='day-trips')return $p['category']==='Day Trips';return true;});foreach($filter as $p):?><article class="trip-card"><div class="trip-body"><span><?=e($p['days'])?> day<?= $p['days']==1?'':'s' ?></span><h3><?=e($p['title'])?></h3><p><?=e($p['summary'])?></p><a href="/package/<?=e($p['slug'])?>">View itinerary →</a></div></article><?php endforeach;?></div><?php elseif($slug==='faq'):?><div class="faq"><details open><summary>Can I combine safari, Kilimanjaro and Zanzibar?</summary><p>Yes. Tanzania Wildlife Epic can structure a combined itinerary around your available days and preferred travel style.</p></details><details><summary>Are wildlife sightings guaranteed?</summary><p>No. Wildlife is wild and natural sightings cannot be guaranteed.</p></details><details><summary>Why are some prices not shown?</summary><p>Prices are shown only when verified. Otherwise the site uses Request a Quote.</p></details></div><?php else:?><div class="prose"><h2>Travel planning built around Tanzania</h2><p>Tanzania Wildlife Epic focuses on Tanzania itineraries spanning wildlife safaris, mountain trekking, Zanzibar and selected day experiences. This rebuild keeps business information conservative and avoids unverified claims.</p><p>Use the enquiry form to request an itinerary built around your dates, trip length and preferred travel style.</p><a class="btn gold" href="/contact">Plan Your Trip</a></div><?php endif;?></section></main><?php require __DIR__.'/includes/footer.php';?>
